from pathlib import Path

ROOT = Path('/Volumes/TOSHIBA EXT/College Essay')

def replace_once(text: str, old: str, new: str, label: str) -> str:
    if old not in text:
        raise RuntimeError(f'missing block: {label}')
    return text.replace(old, new, 1)

# Patch direction.ts
path = ROOT / 'src/lib/fm/direction.ts'
text = path.read_text()

text = replace_once(
    text,
    """function jaccardOverlap(a: string, b: string): number {\n  const A = new Set(tokenizeForOverlap(a));\n  const B = new Set(tokenizeForOverlap(b));\n  if (A.size === 0 || B.size === 0) return 0;\n  let inter = 0;\n  for (const x of A) if (B.has(x)) inter += 1;\n  const union = A.size + B.size - inter;\n  return union === 0 ? 0 : inter / union;\n}\n\nfunction familyFitScore(pattern: NarrativePattern, family: RuntimeDirectionCandidate['family_type']): number {\n""",
    """function jaccardOverlap(a: string, b: string): number {\n  const A = new Set(tokenizeForOverlap(a));\n  const B = new Set(tokenizeForOverlap(b));\n  if (A.size === 0 || B.size === 0) return 0;\n  let inter = 0;\n  for (const x of A) if (B.has(x)) inter += 1;\n  const union = A.size + B.size - inter;\n  return union === 0 ? 0 : inter / union;\n}\n\nconst RUNTIME_DIRECTION_FAMILIES: Array<RuntimeDirectionCandidate['family_type']> = [\n  'tension',\n  'value',\n  'process',\n  'relationship',\n  'contradiction',\n  'realization',\n  'ambiguity',\n];\n\nfunction patternBestFamilyFit(pattern: NarrativePattern): number {\n  return Math.max(...RUNTIME_DIRECTION_FAMILIES.map((family) => familyFitScore(pattern, family)));\n}\n\nfunction familyFitScore(pattern: NarrativePattern, family: RuntimeDirectionCandidate['family_type']): number {\n""",
    'insert helpers'
)

text = replace_once(
    text,
    """    const contradictionOverusePenalty = clampScore(\n      candidate.family_type === 'contradiction'\n      && !['conflict_reframe', 'identity_shift', 'failure_reinterpretation'].includes(pattern)\n        ? 0.46\n        : 0\n    );\n    const familyMismatchPenalty = clampScore(Math.max(0, 0.92 - familyFit) + familySignalMismatchPenalty * 0.4);\n    const familyCollapsePenalty = clampScore(decisionShellPattern.test(`${candidate.direction_line} ${candidate.essay_about}`) ? 0.82 : 0.04);\n    const decisionShellPenalty = clampScore(decisionShellPattern.test(`${candidate.direction_line} ${candidate.essay_about} ${candidate.why_this_direction}`) ? 0.84 : 0.06);\n    const hasAltFamilySignal = processSignalHit || relationshipSignalHit || contradictionSignalHit || researchSignalHit\n      || ['process', 'relationship', 'contradiction', 'realization'].some((family) => familyFitScore(pattern, family as RuntimeDirectionCandidate['family_type']) > 0.82);\n    const dominantFamilyOverusePenalty = clampScore(\n      ((candidate.family_type === 'tension' || candidate.family_type === 'value') && hasAltFamilySignal\n        ? 0.56\n        : 0)\n      + (candidate.family_type === 'process' && !processSignalHit && (relationshipSignalHit || contradictionSignalHit || pattern === 'conflict_reframe' || pattern === 'identity_shift')\n        ? 0.34\n        : 0)\n      + 0.06\n    );\n""",
    """    const contradictionOverusePenalty = clampScore(\n      candidate.family_type === 'contradiction'\n      && !['conflict_reframe', 'identity_shift', 'failure_reinterpretation'].includes(pattern)\n        ? 0.46\n        : 0\n    );\n    const patternBestFit = patternBestFamilyFit(pattern);\n    const familyFitGap = clampScore(patternBestFit - familyFitBase);\n    const familyMismatchPenalty = clampScore(Math.max(0, 0.92 - familyFit) + familySignalMismatchPenalty * 0.4);\n    const familyCollapsePenalty = clampScore(decisionShellPattern.test(`${candidate.direction_line} ${candidate.essay_about}`) ? 0.82 : 0.04);\n    const decisionShellPenalty = clampScore(decisionShellPattern.test(`${candidate.direction_line} ${candidate.essay_about} ${candidate.why_this_direction}`) ? 0.84 : 0.06);\n    const hasAltFamilySignal = processSignalHit || relationshipSignalHit || contradictionSignalHit || researchSignalHit\n      || ['process', 'relationship', 'contradiction', 'realization'].some((family) => familyFitScore(pattern, family as RuntimeDirectionCandidate['family_type']) > 0.82);\n    const patternConditionedMisfitPenalty = clampScore(\n      familyFitGap * 1.25 +\n      Math.max(0, 0.84 - familyFit) * 0.45 +\n      familySignalMismatchPenalty * 0.45 -\n      familySignalBoost * 0.15\n    );\n    const dominantFamilyOverusePenalty = clampScore(\n      (familyFitGap > 0.18 && hasAltFamilySignal ? 0.42 : 0)\n      + (familyFitGap > 0.1 ? familyFitGap * 0.35 : 0)\n      + 0.06\n    );\n""",
    'replace local family penalties'
)

text = replace_once(
    text,
    """    // Apply realization misfit penalty: penalize when realization has low pattern fit\n    const realizationMisfitPenalty = clampScore(\n      candidate.family_type === 'realization' && familyFit < 0.92\n        ? (0.92 - familyFit) * 2.8\n        : 0\n    );\n    const postPenaltyTotal = round(\n      prePenaltyTotal -\n      translationPenalty * 0.07 -\n      templateScaffoldPenalty * 0.12 -\n      abstractionPenalty * 0.06 -\n      identifiabilityPenalty * 0.12 -\n      essayAboutRedundancyPenalty * 0.28 -\n      familyCollapsePenalty * 0.28 -\n      decisionShellPenalty * 0.24 -\n      dominantFamilyOverusePenalty * 0.26 -\n      contradictionOverusePenalty * 0.9 -\n      familyMismatchPenalty * 0.16 -\n      realizationMisfitPenalty * 1.0\n    );\n""",
    """    const postPenaltyTotal = round(\n      prePenaltyTotal -\n      translationPenalty * 0.07 -\n      templateScaffoldPenalty * 0.12 -\n      abstractionPenalty * 0.06 -\n      identifiabilityPenalty * 0.12 -\n      essayAboutRedundancyPenalty * 0.28 -\n      familyCollapsePenalty * 0.28 -\n      decisionShellPenalty * 0.24 -\n      dominantFamilyOverusePenalty * 0.26 -\n      contradictionOverusePenalty * 0.16 -\n      familyMismatchPenalty * 0.16 -\n      patternConditionedMisfitPenalty * 0.34\n    );\n""",
    'replace post penalty block'
)

text = replace_once(
    text,
    """        ambiguity_decision_helpfulness: ambiguityDecisionHelpfulness,\n        source_grounding: sourceGrounding,\n        source_faithfulness: sourceFaithfulness,\n        essay_aboutness_clarity: essayAboutnessClarity,\n""",
    """        ambiguity_decision_helpfulness: ambiguityDecisionHelpfulness,\n        source_grounding: sourceGrounding,\n        source_faithfulness: sourceFaithfulness,\n        family_fit_base: familyFitBase,\n        family_fit: familyFit,\n        family_fit_gap: familyFitGap,\n        pattern_conditioned_misfit_penalty: patternConditionedMisfitPenalty,\n        essay_aboutness_clarity: essayAboutnessClarity,\n""",
    'add debug fit fields'
)

text = replace_once(
    text,
    """        batch_diversity_credit: 0,\n        packet_family_sameness_penalty: 0,\n        batch_family_distribution_penalty: 0,\n      },\n""",
    """        batch_diversity_credit: 0,\n        packet_family_sameness_penalty: 0,\n        batch_family_distribution_penalty: 0,\n        packet_adjusted_total: totalScore,\n      },\n""",
    'add packet adjusted total'
)

text = replace_once(
    text,
    """  const diversityAdjusted = applySelectionDiversity(sorted);\n  const contradictionAllowedPrimary = pattern === 'conflict_reframe' || pattern === 'identity_shift';\n  const contradictionMarginRequired = pattern === 'failure_reinterpretation' ? 0.04 : 0.01;\n  if (diversityAdjusted.length > 1 && diversityAdjusted[0].family_type === 'contradiction' && !contradictionAllowedPrimary) {\n    const bestNonContradiction = diversityAdjusted.find((c) => c.family_type !== 'contradiction' && c.rejection_reasons.length < 2);\n    if (bestNonContradiction) {\n      const contradictionLead = diversityAdjusted[0].scores.total_score - bestNonContradiction.scores.total_score;\n      if (contradictionLead < contradictionMarginRequired) {\n        const forced = [\n          bestNonContradiction,\n          ...diversityAdjusted.filter((c) => c.candidate_id !== bestNonContradiction.candidate_id),\n        ];\n        return forced.map((c, i) => ({ ...c, selected: i === 0, rank: i + 1 }));\n      }\n    }\n  }\n\n  // Realization demotion: check raw sorted scores BEFORE diversity adjustment.\n  // If realization is in top 2 but another family is within 0.02 margin, demote realization\n  if (sorted.length >= 2 && sorted[0].family_type === 'realization') {\n    const second = sorted[1];\n    if (second.family_type !== 'realization') {\n      const realizationLead = sorted[0].scores.total_score - second.scores.total_score;\n      if (realizationLead < 0.005) {\n        const forced = [second, ...diversityAdjusted.filter((c) => c.candidate_id !== second.candidate_id)];\n        return forced.map((c, i) => ({ ...c, selected: i === 0, rank: i + 1 }));\n      }\n    }\n  }\n  if (!needsDominanceCap) return diversityAdjusted;\n""",
    """  const diversityAdjusted = applySelectionDiversity(sorted);\n  if (diversityAdjusted.length > 1) {\n    const top = diversityAdjusted[0];\n    const bestAlternative = diversityAdjusted.find((c) => c.family_type !== top.family_type && c.rejection_reasons.length < 2);\n    if (bestAlternative) {\n      const lead = top.scores.total_score - bestAlternative.scores.total_score;\n      const fitGap = top.scores.family_fit_gap ?? 0;\n      const misfitPenalty = top.scores.pattern_conditioned_misfit_penalty ?? 0;\n      if ((fitGap > 0.18 || misfitPenalty > 0.24) && lead <= 0.05) {\n        const forced = [bestAlternative, ...diversityAdjusted.filter((c) => c.candidate_id !== bestAlternative.candidate_id)];\n        return forced.map((c, i) => ({ ...c, selected: i === 0, rank: i + 1 }));\n      }\n    }\n  }\n  if (!needsDominanceCap) return diversityAdjusted;\n""",
    'replace winner swap logic'
)

path.write_text(text)

# Patch holdout script
path = ROOT / 'scripts/page3-holdout-v2.mjs'
text = path.read_text()

text = replace_once(
    text,
    "const OUT_BLIND_KEY = path.join(OUT_DIR, 'blind_review_answer_key.json');\n",
    "const OUT_BLIND_KEY = path.join(OUT_DIR, 'blind_review_answer_key.json');\nconst DOMINANT_FAMILY_CAP = Number(process.env.DOMINANT_FAMILY_CAP ?? '0.35');\n",
    'add cap const'
)

text = replace_once(
    text,
    """function deterministicSwap(caseId) {\n  let sum = 0;\n  for (const ch of caseId) sum += ch.charCodeAt(0);\n  return sum % 2 === 1;\n}\n\nfunction buildBlindPacket(rows) {\n""",
    """function deterministicSwap(caseId) {\n  let sum = 0;\n  for (const ch of caseId) sum += ch.charCodeAt(0);\n  return sum % 2 === 1;\n}\n\nfunction clampNumber(value, min = 0, max = 1) {\n  return Math.min(max, Math.max(min, value));\n}\n\nfunction getProductCandidates(row) {\n  return row?.product?.canonical_payload?.candidate_debug?.scores_by_candidate ?? [];\n}\n\nfunction getInitialWinnerId(row, candidates) {\n  const winnerId = row?.product?.canonical_payload?.candidate_debug?.winner_id;\n  if (winnerId && candidates.some((candidate) => candidate.id === winnerId)) return winnerId;\n  return candidates[0]?.id ?? null;\n}\n\nfunction buildFamilyCounts(rows, selectionByCase) {\n  const counts = new Map();\n  for (const row of rows) {\n    const candidates = getProductCandidates(row);\n    const winnerId = selectionByCase.get(row.case_id);\n    const selected = candidates.find((candidate) => candidate.id === winnerId);\n    const family = selected?.recommendation_family;\n    if (!family) continue;\n    counts.set(family, (counts.get(family) ?? 0) + 1);\n  }\n  return counts;\n}\n\nfunction dominanceObjective(counts, totalCases) {\n  const capCount = DOMINANT_FAMILY_CAP * totalCases;\n  let total = 0;\n  for (const count of counts.values()) {\n    const overflow = Math.max(0, count - capCount);\n    total += overflow * overflow;\n  }\n  return total;\n}\n\nfunction packetPressureForFamily(family, counts, totalCases) {\n  const count = counts.get(family) ?? 0;\n  const ratio = totalCases > 0 ? count / totalCases : 0;\n  const packetFamilySamenessPenalty = Number(clampNumber((count - 1) / Math.max(totalCases - 1, 1)).toFixed(3));\n  const batchFamilyDistributionPenalty = Number(clampNumber((ratio - DOMINANT_FAMILY_CAP) / Math.max(1 - DOMINANT_FAMILY_CAP, 0.01)).toFixed(3));\n  return { packetFamilySamenessPenalty, batchFamilyDistributionPenalty };\n}\n\nfunction packetAdjustedTotal(candidate, counts, totalCases) {\n  const family = candidate?.recommendation_family;\n  if (!family) return Number(candidate?.total ?? 0);\n  const pressure = packetPressureForFamily(family, counts, totalCases);\n  return Number(((candidate.total ?? 0) - pressure.packetFamilySamenessPenalty * 0.18 - pressure.batchFamilyDistributionPenalty * 0.46).toFixed(3));\n}\n\nfunction applyPacketFamilyPressure(rows) {\n  const productRows = rows.filter((row) => getProductCandidates(row).length > 0);\n  const totalCases = productRows.length;\n  if (totalCases === 0) return rows;\n\n  const selectionByCase = new Map(productRows.map((row) => [row.case_id, getInitialWinnerId(row, getProductCandidates(row))]));\n\n  for (let iter = 0; iter < totalCases * 6; iter += 1) {\n    const counts = buildFamilyCounts(productRows, selectionByCase);\n    const currentObjective = dominanceObjective(counts, totalCases);\n    const dominantRatio = Math.max(...Array.from(counts.values(), (count) => count / totalCases), 0);\n    if (dominantRatio <= DOMINANT_FAMILY_CAP || currentObjective <= 0) break;\n\n    let bestSwitch = null;\n    for (const row of productRows) {\n      const candidates = getProductCandidates(row);\n      const currentId = selectionByCase.get(row.case_id);\n      const current = candidates.find((candidate) => candidate.id === currentId);\n      if (!current?.recommendation_family) continue;\n\n      const currentEffective = packetAdjustedTotal(current, counts, totalCases);\n      for (const candidate of candidates) {\n        if (!candidate?.recommendation_family || candidate.id === current.id) continue;\n        if (candidate.recommendation_family === current.recommendation_family) continue;\n\n        const nextCounts = new Map(counts);\n        nextCounts.set(current.recommendation_family, Math.max(0, (nextCounts.get(current.recommendation_family) ?? 1) - 1));\n        nextCounts.set(candidate.recommendation_family, (nextCounts.get(candidate.recommendation_family) ?? 0) + 1);\n\n        const nextObjective = dominanceObjective(nextCounts, totalCases);\n        if (nextObjective >= currentObjective) continue;\n\n        const alternativeEffective = packetAdjustedTotal(candidate, nextCounts, totalCases);\n        const scoreLoss = Number((currentEffective - alternativeEffective).toFixed(3));\n        const objectiveGain = Number((currentObjective - nextObjective).toFixed(3));\n        if (scoreLoss > 0.16 && objectiveGain < 1) continue;\n\n        const rank = Number((scoreLoss / Math.max(objectiveGain, 0.001)).toFixed(3));\n        if (!bestSwitch || rank < bestSwitch.rank || (rank == bestSwitch.rank and scoreLoss < bestSwitch.scoreLoss)):\n          pass\n""",
    'insert packet pressure helpers'
)
